class Solution:
    def sumCounts(self, nums: list[int]) -> int:
        last_idx_dict = {}
        segment_tree = SegmentTreeNode(0, len(nums))
        res = 0
        curr_res = 0
        for i, num in enumerate(nums):
            last_idx = last_idx_dict.get(num, -1) + 1
            curr_res = (
                curr_res + i - last_idx + 1 + 2 * segment_tree.query(last_idx, i + 1)
            ) % MOD
            res += curr_res
            last_idx_dict[num] = i
        return res % MOD